ERROR_FILE = "errors.json"  # 错误记录文件

# 设置日志
# 设置日志同时输出到控制台和文件
log_file = "logs/processing.log"  # 日志文件路径
log_dir = os.path.dirname(log_file)
# 如果目录不存在，则创建（包括父目录）
if not os.path.exists(log_dir):
    os.makedirs(log_dir)

# 创建控制台处理器（输出到终端）
console_handler = logging.StreamHandler()
console_handler.setLevel(logging.INFO)
console_format = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
console_handler.setFormatter(console_format)

# 获取根 logger，添加控制台 handler（先清空已有 handler，防止重复）
root_logger = logging.getLogger()
# 如果已有 handler 不想清除，可改为判断是否已存在 console_handler 但更干净的方式：先清空再添加
for h in root_logger.handlers[:]:
    root_logger.removeHandler(h)
root_logger.addHandler(console_handler)
root_logger.setLevel(logging.INFO)

logger = logging.getLogger(__name__)

# 全局锁
write_lock = Lock()

""" 打印AI 回答 """


def print_response_detail(res, haoshi):
    logger.debug(f"====== 本次AI回答情况 ======")
    logger.debug(f"本次请求ID： {res.id}")
    logger.debug(f"本次AI回答： {res.choices[0].message.content}")

    # 安全获取 usage 相关信息
    usage = getattr(res, 'usage', None)
    if usage:
        logger.info(f"本次输入消耗的 token 数： {getattr(usage, 'prompt_tokens', 'N/A')}")
        logger.info(f"本次输出消耗的 token 数： {getattr(usage, 'completion_tokens', 'N/A')}")
        logger.info(f"本次消耗的总 token 数： {getattr(usage, 'total_tokens', 'N/A')}")

        # 思考消耗的 token 数（部分模型支持）
        completion_details = getattr(usage, 'completion_tokens_details', None)
        if completion_details and hasattr(completion_details, 'reasoning_tokens'):
            reasoning_tokens = completion_details.reasoning_tokens
        else:
            reasoning_tokens = 'N/A (not supported)'
        logger.info(f"本次思考消耗的 token 数： {reasoning_tokens}")

        # 缓存命中 token 数
        cache_hit = getattr(usage, 'prompt_cache_hit_tokens', None)
        if cache_hit is None:
            cache_hit = 'N/A (not supported)'
        logger.info(f"从缓存中命中的 token 数： {cache_hit}")
    else:
        logger.info("本次 token 消耗信息： N/A (usage missing)")

    logger.info(f"本次回答总耗时： {haoshi} 秒")
    logger.debug(f"本次AI返回： {res.choices[0].message}")
    logger.debug('--' * 10)


# ---------- 辅助函数 ----------
""" 辅助函数：修剪历史，只保留最近 MAX_HISTORY_TURNS 轮（但始终保留第一条 system）"""


def trim_history(messages, max_turns: int = 1):
    """保留 system 消息 + 最近 max_turns 轮 user/assistant 对"""
    # 第一条是 system
    if not messages or messages[0]["role"] != "system":
        return messages
    system_msg = messages[0]
    # 剩下的对话对
    rest = messages[1:]
    # 每轮由 user + assistant 组成，所以切割时按 2 条消息为一个单位
    if len(rest) > max_turns * 2:
        rest = rest[-(max_turns * 2):]
    return [system_msg] + rest


"""装饰器：处理API限流和临时错误"""


def retry_on_rate_limit(max_retries=MAX_RETRIES, delay=RETRY_DELAY):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(max_retries):
                try:
                    return func(*args, **kwargs)
                except RateLimitError as e:
                    wait = delay * (2 ** attempt)
                    logger.warning(f"Rate limit hit, retrying in {wait}s... (attempt {attempt + 1}/{max_retries})")
                    time.sleep(wait)
                except APIError as e:
                    if attempt < max_retries - 1:
                        wait = delay * (2 ** attempt)
                        logger.warning(f"API error: {e}, retrying in {wait}s...")
                        time.sleep(wait)
                    else:
                        raise
                except Exception as e:
                    logger.error(f"Unhandled error: {e}")
                    raise
            raise Exception(f"Failed after {max_retries} retries")

        return wrapper

    return decorator


"""线程安全地向JSON文件追加一条记录（避免并发写入冲突）"""


def safe_append_to_json(file_path, new_data):
    with write_lock:
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                data = json.load(f)
        except (FileNotFoundError, json.JSONDecodeError):
            data = []
        data.append(new_data)
        with open(file_path, 'w', encoding='utf-8') as f:
            json.dump(data, f, ensure_ascii=False, indent=2)


"""线程安全地读取 JSON 文件并返回完整数据（列表或字典等）"""


def safe_read_from_json(file_path):
    with write_lock:
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                data = json.load(f)
        except (FileNotFoundError, json.JSONDecodeError):
            data = []  # 或 {}，根据您的业务决定
        return data


"""线程安全地向文本文件追加一行"""


def safe_append_to_file(file_path, line):
    with write_lock:
        with open(file_path, 'a', encoding='utf-8') as f:
            f.write(line + '\n')


"""线程安全地读取文本文件的所有行，返回字符串列表"""


def safe_read_from_file(file_path):
    with write_lock:
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                lines = f.readlines()
        except FileNotFoundError:
            lines = []
        # 如果需要去除换行符，可使用 strip 或 rstrip('\n')
        return [line.rstrip('\n') for line in lines]


