def process_all_patients(patient_list, max_workers=MAX_WORKERS):
    """ 使用线程池执行 并行处理多个患者"""
    # 一次处理一个科室，然后按照数量进行批次处理 一个批次处理
    logger.info(f"开始处理科室 {dept_name} 共有 {len(patient_list) if patient_list else 0} 个患者")
    if not patient_list:
        return

    # ---------- 2. 预读 DIP 目录库并缓存每个前缀的过滤结果 ----------
    # 定义合并规则，有些科室病种不能分的太细
    MERGE_GROUPS = {
        'I': ['I0', 'I2', 'I3', 'I4', 'I5'],
        # 未来可增加，例如：
        # 'A': ['A1', 'A2'],
    }
    # 构建前缀→组名映射
    prefix_to_group = {}
    for group_name, prefixes in MERGE_GROUPS.items():
        for p in prefixes:
            prefix_to_group[p] = group_name

    # ---------- 2. 预扫描数据，收集原始前缀、组名及组→前缀列表 ----------
    group_to_prefixes = defaultdict(list)  # 组名 → 该组包含的所有原始前缀（去重）
    group_names = set()  # 所有用到的组名
    temp_data = []  # 暂存每项的原始前缀，避免二次计算（可选）

    for item in patient_list:
        try:
            zhenduan = item.get('病案诊断', '') if item.get('病案诊断', '') else item.get('诊断', '')
            if not zhenduan:
                logger.warning(f"患者 {item.get('医保结算流水号')} 病案诊断为空")
                continue
            match = re.search(r'\(([^)]+)\)', zhenduan)
            if not match:
                logger.warning(f"患者 {item.get('医保结算流水号')} 病案诊断无匹配项")
                continue
            dip_code = match.group(1)
            original_pref = dip_code[:2] if len(dip_code) >= 2 else (dip_code + '0' if dip_code else '未知')
            group_key = prefix_to_group.get(original_pref, original_pref)
            group_names.add(group_key)
            if original_pref not in group_to_prefixes[group_key]:
                group_to_prefixes[group_key].append(original_pref)
            # 可将 (item, original_pref, group_key) 暂存，供后续分组直接用，减少再次遍历
            temp_data.append((item, original_pref, group_key))
        except Exception:
            pass

    # ---------- 3. 按组生成 DIP 目录库缓存（替代原 filter_excel_cache 逻辑） ----------
    filtered_excel_cache = {}
    dip_path = '/Users/gaoyanliang/各个系统文档整理/ai-dip/各科室患者DIP数据/脑病重症病区/2026年DIP病种目录库.xlsx' \
        if global_config.run_in_local else '/home/gyl/2026年DIP病种目录库.xlsx'
    if os.path.exists(dip_path):
        try:

            df_dip = pd.read_excel(dip_path, dtype=str, engine='openpyxl')
            df_dip['诊断编码'] = df_dip['诊断编码'].astype(str).str.strip().fillna('')

            for gname, prefixes_list in group_to_prefixes.items():
                if '未知' in prefixes_list:
                    df_filtered = df_dip
                else:
                    df_filtered = df_dip[df_dip['诊断编码'].str[:2].isin(prefixes_list)]

                if df_filtered.empty:
                    logging.warning(f"组 {gname} 的前缀 {prefixes_list} 在目录库中无匹配项，将使用完整目录库")
                    df_filtered = df_dip

                filtered_excel_cache[gname] = df_filtered.to_dict(orient='records')  # 直接存字典列表
        except Exception as e:
            logging.error(f"读取/过滤目录库失败: {e}")
            return
    else:
        # 文件不存在，填充提示信息
        logger.error("标准目录库 文件不存在")
        return

    # ---------- 3. 按 DIP 前缀分组 ----------
    grouped = defaultdict(list)
    for item, original_pref, group_key in temp_data:
        grouped[group_key].append(item)

    # ---------- 4. 生成总 ZIP ----------
    worker_count = min(int(len(grouped) / 2), max_workers)
    worker_count = worker_count if worker_count > 0 else 1
    with ThreadPoolExecutor(max_workers=worker_count) as executor:
        futures = {}
        for dip_prefix, patients in grouped.items():
            # 准备当前分组的额外文件
            muluku_list = filtered_excel_cache.get(dip_prefix, [])
            logger.info(f"{dip_prefix} 目录裤数量 {len(muluku_list)}")
            logger.info(f"{dip_prefix} 患者数量 {len(patients)}")

            future = executor.submit(call_ai_for_patient, patients, muluku_list)
            futures[future] = dip_prefix

        for future in as_completed(futures):
            dip_prefix = futures[future]
            try:
                # call_ai_for_patient 返回的是一个列表，每个元素对应一个患者的 AI 响应
                ai_responses = future.result()  # List[str]
                logger.info(f" {dept_name} {dip_prefix} 批处理完成，共 {len(ai_responses)} 个患者")
            except Exception as e:
                logger.error(f"{dept_name} - {dip_prefix} 批处理失败: {e} {traceback.format_exc()}")


"""
根据总人数计算每批的大小，使得批次数尽量少，且每批在 50~80 之间，
批次间人数尽量平均（相差不超过1）。
"""
def get_batch_sizes(total: int):
    if total <= 0:
        return []
    if total <= CONFIG['batch_min']:
        return [total]  # 人数不足，只能一批

    groups = (total + CONFIG['batch_max'] - 1) // CONFIG['batch_max']  # ceil(total/100)
    base = total // groups
    remainder = total % groups
    # 前 remainder 批多1人
    sizes = [base + 1] * remainder + [base] * (groups - remainder)
    return sizes


"""
将列表 items 按批次分割，返回批次列表。
若 shuffle=True，则先打乱顺序再分割（可选）。
"""
def split_into_batches(items: list, shuffle: bool = False):
    if not items:
        return []
    total = len(items)
    sizes = get_batch_sizes(total)
    # 若需要随机分布，可先打乱（注意会影响原始顺序）
    if shuffle:
        import random
        items_copy = items.copy()
        random.shuffle(items_copy)
    else:
        items_copy = items

    batches = []
    start = 0
    for size in sizes:
        batches.append(items_copy[start:start + size])
        start += size
    return batches



